INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (15775, 'Omapuriro ja Kariza', 'otjiherero', 'Kariza uahongua okupura omapuriro. Okupura kuemuhonga ovina ovingi tjimuna okurikoha no ku koha omake tjiuazu no kurija. Nível: Longer paragraphs. Ilustração: Rob Owen.', 'http://africanstorybook.org/illustrations/covers/33467.png', NULL, 2526, 35, 30, 'asp-33467', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (15776, 'Ehandukilo', 'oshikwanyama', 'Ehandukilo li li ngahelipi mbela ta li dulu oku pewa okaana kafuka aka kalya oiimati ihapu unene? Nível: First sentences. Ilustração: Melany Pietersen.', 'http://africanstorybook.org/illustrations/covers/33468.png', NULL, 2521, 35, 30, 'asp-33468', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (15777, 'Omapulo aKariza', 'oshikwanyama', 'Kariza okwa li a mutwa omukumo kovakulunhu aye a kale ta pula omapulo. Oku pula kwaye oko kwe mu kwafa a shiive kombinga yoku likosha keenyala Nível: Longer paragraphs. Ilustração: Rob Owen.', 'http://africanstorybook.org/illustrations/covers/33469.png', NULL, 2521, 35, 30, 'asp-33469', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (15778, 'Egeelo', 'oshindonga', 'Egeelo lini ta li vulu oku pewa okanona ke hole okulya no ka li iiyimati oyindji unene? Nível: First sentences. Ilustração: Melany Pietersen.', 'http://africanstorybook.org/illustrations/covers/33470.png', NULL, 2521, 35, 30, 'asp-33470', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (15779, 'Omapulo gaKariza', 'oshindonga', 'Kariza okwa li alaadhipikwa kaakuluntu ye opo a pule omapulo. Oku pula omapulo okwa kwathele Kariza atseye oshindji kombinga yoku iyoga komake nankene sha simana oku iyoga komake manga inaa tu lya. Nível: Longer paragraphs. Ilustração: Rob Owen.', 'http://africanstorybook.org/illustrations/covers/33471.png', NULL, 2521, 35, 30, 'asp-33471', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (15780, 'Edewuro', 'rukwangali', 'Edewuro musinke no pa ogu mumati gomakurulya anamana kulya enyango lyenzi. Nível: First sentences. Ilustração: Melany Pietersen.', 'http://africanstorybook.org/illustrations/covers/33474.png', NULL, 2923, 35, 30, 'asp-33474', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (15781, 'Epuro lya Kazira', 'rukwangali', 'Kazira ngava mukorangeda vakurona vendi apure mapuro. Kupura mapuro kwamu twaredesere aka dive nonzira doku kuhwa yiruganeso ntani no mulyo gokulikuhwa komawoko komeho zokulya. Nível: Longer paragraphs. Ilustração: Rob Owen.', 'http://africanstorybook.org/illustrations/covers/33475.png', NULL, 2923, 35, 30, 'asp-33475', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (15782, 'Mut''u mure zhomu', 'kigiryama', 'Ye mutu kwenye ngano ii ni mure tha kila kitu kwake ni kifuti hedu kithithe. Anagonya thabuze kwa kutengeza vitu vithuwazho kimoche. Nível: First words. Ilustração: Catherine Groenewald.', 'http://africanstorybook.org/illustrations/covers/33476.png', NULL, 2924, 35, 30, 'asp-33476', 'cc-by', 0, NULL);
